// STRICT NULL HANDLING — SQLITE COLUMN SANITIZER
// Implement sanitizeColumn and formatTagList!

export function sanitizeColumn(val: string | null | undefined): string {
  return val ?? "N/A";
}

export function formatTagList(tags: string | null): string[] {
  if (!tags) return [];
  return tags.split(",").map(t => t.trim());
}

